import random

class RandomWalker:
    # Constructor
    def __init__(self):
        self.position = 0

    # Walk n steps forward from 0 - each step updates the state of the object with a random increment.
    def walk(self, n):
        self.position = 0
        for i in range(n):
            yield self.position
            self.position += 2 * random.randint(0, 1) - 1
